/**
 * Scan for Wi-Fi networks or save Wi-Fi credentials (mutating on save)
 *
 * ONE endpoint with two modes selected by the `action` query parameter. This
 * is modelled as a single POST operation because the `save` mode needs a
 * request body; note that in the firmware the `scan` mode is actually invoked
 * as a GET with no body. The response schema is a oneOf of the two shapes.
 *
 * - `action=scan`: returns `{"wifi":[...]}` - an array of ESSID strings,
 * ALWAYS terminated by an empty-string element `""` to absorb the trailing
 * comma. SSIDs are injected raw/unescaped and are not guaranteed valid JSON.
 * - `action=save` (mutating): reads a one-line JSON body with WIFI_ESSID,
 * WIFI_PASSWORD, WIFI_PASSWORD2. If the JSON is valid and WIFI_PASSWORD ==
 * WIFI_PASSWORD2, it writes the credentials, runs configure_wifi.sh (then
 * `sleep 1`) and returns `{"error":"false"}`; invalid JSON or a password
 * mismatch returns `{"error":"true"}`. Body values bypass all validators
 * (only JSON validity is enforced).
 *
 * Only the FIRST `=`-delimited pair is parsed for `action`, so `action` must
 * be the sole query parameter. Any action other than scan/save yields an
 * EMPTY response with no headers.
 */
export const wifiMutation = (options?: Partial<Options<WifiData>>): UseMutationOptions<WifiResponse, AxiosError<DefaultError>, Options<WifiData>> => {
    const mutationOptions: UseMutationOptions<WifiResponse, AxiosError<DefaultError>, Options<WifiData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await wifi({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Speak text through the camera speaker (text-to-speech)
 *
 * Synthesises the POST body text via nanotts and plays it through the
 * speaker. The body is read with `read -r` (first line only), is NOT
 * validated, and is echoed unescaped into the response `description` (a `"`
 * in the text breaks the JSON). Success path runs `sleep 1`.
 *
 * At most 2 query params are parsed. `lang` (default `en-US`) must pass
 * validateLang: exactly 5 chars matching `[A-Za-z-]` (so `en_US` and `en`
 * are rejected). Volume is set by either `vol` (linear, `pcmvol -g`) or
 * `voldb` (dB, `pcmvol -G`); whichever is processed LAST wins (order
 * matters). Both use validateNumber.
 *
 * Failure descriptions include "Invalid language", "Invalid volume",
 * "Invalid volume (dB)", "Speaker busy", "TTS engine not found",
 * "Audio input disabled". NOTE: the lang/vol/voldb validation-failure
 * branches emit the JSON body WITHOUT a Content-type header.
 */
export const speakTextMutation = (options?: Partial<Options<SpeakTextData>>): UseMutationOptions<SpeakTextResponse, AxiosError<DefaultError>, Options<SpeakTextData>> => {
    const mutationOptions: UseMutationOptions<SpeakTextResponse, AxiosError<DefaultError>, Options<SpeakTextData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await speakText({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Play an uploaded audio clip through the speaker
 *
 * Plays an uploaded audio payload (multipart form field, or a raw PCM/WAV
 * stream) through the speaker. If the data begins with a multipart boundary
 * the wrapper is stripped heuristically; a leading `RIFF` (WAV header) has
 * its first 4 bytes stripped. The body is not validated.
 *
 * Only the FIRST query param is parsed, so `vol` and `voldb` are mutually
 * exclusive (whichever comes first wins); both use validateNumber. If the SD
 * card is mounted, playback is BACKGROUNDED and success returns immediately
 * (with empty description); if not mounted, playback is synchronous and the
 * body must be <= 512000 bytes or the response is
 * `{"error":"true","description":"File is too big"}`. Missing
 * `/tmp/audio_in_fifo` returns "Audio input is not available". Worst-case
 * blocking `sleep 1`. NOTE: the vol/voldb validateNumber failure branches emit
 * the JSON body WITHOUT a Content-type header (only the query-string-blocklist
 * and later branches include it).
 */
export const playAudioMutation = (options?: Partial<Options<PlayAudioData>>): UseMutationOptions<PlayAudioResponse, AxiosError<DefaultError>, Options<PlayAudioData>> => {
    const mutationOptions: UseMutationOptions<PlayAudioResponse, AxiosError<DefaultError>, Options<PlayAudioData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await playAudio({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Play an existing audio file from /tmp/sd/audio
 *
 * Plays a pre-existing file from `/tmp/sd/audio/`. The POST body (first line
 * only) is the FILENAME. WARNING: the filename is NOT validated and is used
 * UNQUOTED, so path traversal (e.g. `../../etc/passwd`) is possible. Success
 * runs `sleep 1`. No stock frontend caller.
 *
 * Only `voldb` is honoured (always dB via `pcmvol -G`); there is no linear
 * option. KNOWN BUGS: the "File not found" and "Audio input disabled" JSON
 * bodies are MALFORMED (missing the comma between `error` and `description`).
 * Parse defensively. NOTE: the voldb validateNumber failure branch emits its
 * JSON body WITHOUT a Content-type header (the header is printed only after
 * that check).
 */
export const playAudioFileMutation = (options?: Partial<Options<PlayAudioFileData>>): UseMutationOptions<PlayAudioFileResponse, AxiosError<DefaultError>, Options<PlayAudioFileData>> => {
    const mutationOptions: UseMutationOptions<PlayAudioFileResponse, AxiosError<DefaultError>, Options<PlayAudioFileData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await playAudioFile({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

export const firmwareUpgradeQueryKey = (options: Options<FirmwareUpgradeData>) => createQueryKey('firmwareUpgrade', options);

/**
 * Query firmware version or trigger a firmware upgrade (mutating GET)
 *
 * Two modes selected by the required `get` parameter (which must be the sole
 * query param - the script does `cut -d'='` on the whole string).
 *
 * - `get=info`: returns JSON with fw_version, latest_fw (from a LIVE wget to
 * the GitHub API - empty string if the network call fails), and `local_fw`
 * as a BARE JSON boolean (the one place the API emits a real boolean).
 * - `get=upgrade` (DESTRUCTIVE, mutating): returns `text/html` plain text on
 * all sub-paths (e.g. "No SD detected.", "No space left on SD.", "No new
 * firmware available.", "Unable to download firmware file.", "Download
 * completed, rebooting and upgrading."). It runs `rm -rf` on four /tmp/sd
 * paths BEFORE checking whether the download will succeed, then reboots.
 *
 * A blocklisted query string returns JSON `{"error":"true"}`. A missing/
 * wrong `get` key, or a value outside {info,upgrade}, returns an EMPTY body
 * with no Content-type header.
 */
export const firmwareUpgradeOptions = (options: Options<FirmwareUpgradeData>) => queryOptions<FirmwareUpgradeResponse, AxiosError<DefaultError>, FirmwareUpgradeResponse, ReturnType<typeof firmwareUpgradeQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await firmwareUpgrade({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: firmwareUpgradeQueryKey(options)
});

export const rebootQueryKey = (options?: Options<RebootData>) => createQueryKey('reboot', options);

/**
 * Reboot the camera (DESTRUCTIVE mutating GET)
 *
 * Reboots the camera. Takes no parameters and performs no validation. Returns
 * `{"error":"false"}` FIRST, then runs `sync` x3, `killall mqttv4`,
 * `sleep 1`, and `reboot`. Despite being GET this reboots the device - never
 * prefetch or crawl.
 */
export const rebootOptions = (options?: Options<RebootData>) => queryOptions<RebootResponse, AxiosError<DefaultError>, RebootResponse, ReturnType<typeof rebootQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await reboot({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: rebootQueryKey(options)
});

