export const controlServiceQueryKey = (options?: Options<ControlServiceData>) => createQueryKey('controlService', options);

/**
 * Start/stop/query a camera service (mutating for start/stop)
 *
 * Starts, stops, or queries a camera service by invoking the external
 * service.sh. At most 4 query params are parsed. No stock frontend caller.
 *
 * - `action=status` with a matched `name` returns `{"status":"<RES>"}`, where
 * RES (backend stdout) is injected RAW into the printf format string (not
 * JSON-escaped). `all` is NOT a valid name for status.
 * - `action=start` / `action=stop` (and every unmatched name/action) return
 * `{}` - an empty object with no error and no status, so the client cannot
 * tell success from a typo.
 * - A blocklisted query string returns `{"error":"true"}`.
 *
 * `param1`/`param2` default to the literal string `none` and are forwarded
 * positionally (unquoted) to the backend for rtsp/onvif/ftpd starts.
 */
export const controlServiceOptions = (options?: Options<ControlServiceData>) => queryOptions<ControlServiceResponse, AxiosError<DefaultError>, ControlServiceResponse, ReturnType<typeof controlServiceQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await controlService({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: controlServiceQueryKey(options)
});
